<?php

namespace App\Support;

/**
 * The MotionSites scenes (packages/motionsites): 813 MotionSites prompts
 * ported to standalone NabuXUI pages. Their DemoCatalog manifests
 * (Demos/Ms-*.php) are generated by packages/motionsites/scripts/build.mjs and
 * carry a `scene` key; the demo page then shows the scene in an iframe served
 * by the /motionsites/{slug}.html route, plus its original prompt and source.
 */
class MotionSites
{
    private const SLUG = '/^[a-z][a-z0-9-]*$/';

    private static ?array $catalog = null;

    /** The package root — the playground sits next to it in the monorepo (and in the image). */
    public static function root(): string
    {
        return dirname(base_path()).'/packages/motionsites';
    }

    /** The scene file of a slug, or null when the slug is invalid or not built yet. */
    public static function sceneFile(string $slug): ?string
    {
        if (preg_match(self::SLUG, $slug) !== 1) {
            return null;
        }
        $file = self::root()."/scenes/{$slug}.html";

        return is_file($file) ? $file : null;
    }

    /** The scene's card thumbnail (thumbs/{slug}.webp, made by scripts/thumbs.mjs), or null. */
    public static function thumbFile(string $slug): ?string
    {
        if (preg_match(self::SLUG, $slug) !== 1) {
            return null;
        }
        $file = self::root()."/thumbs/{$slug}.webp";

        return is_file($file) ? $file : null;
    }

    /** The scene's HTML source — the copyable snippet of its demo page. */
    public static function source(string $slug): ?string
    {
        $file = self::sceneFile($slug);

        return $file === null ? null : (string) file_get_contents($file);
    }

    /** The catalog entry (original prompt, media, registry link) of a slug. */
    public static function entry(string $slug): ?array
    {
        if (self::$catalog === null) {
            $raw = @file_get_contents(self::root().'/catalog.json');
            $list = is_string($raw) ? json_decode($raw, true) : null;
            self::$catalog = [];
            foreach (is_array($list) ? $list : [] as $item) {
                self::$catalog[$item['slug']] = $item;
            }
        }

        return self::$catalog[$slug] ?? null;
    }

    /** The original MotionSites prompt of a slug. */
    public static function prompt(string $slug): ?string
    {
        return self::entry($slug)['prompt'] ?? null;
    }
}
